import os
import requests, base64, time

def extract_invoice_fields(payload, config=None):
    config = config or {}
    endpoint = config.get("azure_endpoint", os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT") or "").rstrip("/")
    api_key = config.get("azure_api_key", os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY"))
    url = f"{endpoint}/formrecognizer/documentModels/prebuilt-invoice:analyze?api-version=2023-07-31"
    headers = {"Ocp-Apim-Subscription-Key": api_key, "Content-Type": "application/json"}
    b64 = base64.b64encode(payload if isinstance(payload, bytes) else payload.encode()).decode()
    resp = requests.post(url, headers=headers, json={"base64Source": b64})
    resp.raise_for_status()
    poll_url = resp.headers["Operation-Location"]
    while True:
        poll = requests.get(poll_url, headers=headers)
        poll.raise_for_status()
        st = poll.json().get("status")
        if st == "succeeded": break
        if st == "failed": raise RuntimeError("Analysis failed")
        time.sleep(1)
    res_json = poll.json()
    result = {
        "vendor": res_json["analyzeResult"]["documents"][0]["fields"].get("VendorName", {}).get("content"),
        "date": res_json["analyzeResult"]["documents"][0]["fields"].get("InvoiceDate", {}).get("content"),
        "total": res_json["analyzeResult"]["documents"][0]["fields"].get("InvoiceTotal", {}).get("content"),
        "line_items": [
            {
                "description": i.get("valueObject", {}).get("Description", {}).get("content"),
                "quantity": i.get("valueObject", {}).get("Quantity", {}).get("content"),
                "amount": i.get("valueObject", {}).get("Amount", {}).get("content")
            }
            for i in res_json["analyzeResult"]["documents"][0]["fields"].get("Items", {}).get("valueArray", [])
        ]
    }
    return result
